@dataclass
class ClassInfo:
    name: str
    header: str
    is_value_type: bool = False
    is_detail_class: bool = False  # Classes ending in Details, Detail, Elements, etc.
    static_methods: List[Tuple[str, str, str]] = field(default_factory=list)  # (return_type, method_name, params)
    fields: List[Tuple[str, str]] = field(default_factory=list)  # (type, name)
    base_class: str = ""
    method_name_counts: Dict[str, int] = field(default_factory=dict)



def is_simple_value_type(class_name: str, content: str) -> bool:
    """Check if class is a simple value type with public fields"""
    # Look for pattern: class has public fields like double X{0};
    return False

def is_detail_class(class_name: str) -> bool:
    """Check if class is a 'Details' or data structure class"""
    return any(class_name.endswith(suffix) for suffix in 
               ['Details', 'Detail', 'Elements', 'Date', 'Coordinate', 'Position', 'Orbit'])

def get_class_body(content: str, class_name: str) -> Optional[str]:
    """Return the body of a class definition (inside braces)"""
    class_start = re.search(rf'class\s+AAPLUS_EXT_CLASS\s+{class_name}\b[^{{]*\{{', content)
    if not class_start:
        return None

    pos = class_start.end()
    brace_count = 1
    while pos < len(content) and brace_count > 0:
        if content[pos] == '{':
            brace_count += 1
        elif content[pos] == '}':
            brace_count -= 1
        pos += 1

    if brace_count != 0:
        return None

    return content[class_start.end():pos-1]


def extract_fields(class_body: str) -> List[Tuple[str, str]]:
    """Extract public member fields from a class body"""
    fields: List[Tuple[str, str]] = []

    public_match = re.search(r'public:(.+?)(?:protected:|private:|\Z)', class_body, re.DOTALL)
    if not public_match:
        return fields

    public_section = public_match.group(1)

    field_pattern = re.compile(
        r'^\s*(double|long|int|bool|unsigned)\s+(\w+)\s*(?:\{[^}]*\})?\s*;\s*$'
    )
    depth = 0
    for line in public_section.splitlines():
        depth_before = depth
        depth += line.count('{')
        depth -= line.count('}')

        if depth_before == 0:
            if '(' in line or ')' in line:
                continue
            match = field_pattern.match(line)
            if match:
                field_type, field_name = match.groups()
                if (field_type, field_name) not in fields:
                    fields.append((field_type, field_name))

    return fields

def extract_static_methods(class_body: str) -> List[Tuple[str, str, str]]:
    """Extract public static method declarations from a class body"""
    methods: List[Tuple[str, str, str]] = []

    public_match = re.search(r'public:(.+?)(?:protected:|private:|\Z)', class_body, re.DOTALL)
    if not public_match:
        return methods

    public_section = public_match.group(1)

    patterns = [
        r'\[\[nodiscard\]\]\s+static\s+([\w:<>]+)\s+(\w+)\s*\(([^)]*)\)',
        r'static\s+([\w:<>]+)\s+(\w+)\s*\(([^)]*)\)\s*(?:noexcept)?;',
    ]

    for pattern in patterns:
        for match in re.finditer(pattern, public_section):
            return_type, method_name, params = match.groups()
            return_type = return_type.strip()
            method_name = method_name.strip()
            params = params.strip()

            method_sig = (return_type, method_name, params)
            if method_sig not in methods:
                methods.append(method_sig)

    return methods


def extract_method_name_counts(class_body: str) -> Dict[str, int]:
    """Count all public static method names (including constexpr variants)"""
    counts: Dict[str, int] = {}

    public_match = re.search(r'public:(.+?)(?:protected:|private:|\Z)', class_body, re.DOTALL)
    if not public_match:
        return counts

    public_section = public_match.group(1)

    pattern = re.compile(
        r'(?:\[\[nodiscard\]\]\s+)?(?:constexpr\s+)?static\s+[\w:<>]+\s+(\w+)\s*\('
    )
    for match in pattern.finditer(public_section):
        name = match.group(1)
        counts[name] = counts.get(name, 0) + 1

    return counts

def parse_header_file(filepath: Path) -> List[ClassInfo]:
    """Parse a single header file and extract class information"""
    classes = []
    
    with open(filepath, 'r', encoding='utf-8', errors='ignore') as f:
        content = f.read()
    
    # Find all classes
    class_pattern = r'class\s+AAPLUS_EXT_CLASS\s+(\w+)(?:\s*:\s*public\s+(\w+))?'
    class_matches = re.finditer(class_pattern, content)
    
    for match in class_matches:
        class_name = match.group(1)
        base_class = match.group(2) or ""
        
        class_body = get_class_body(content, class_name)
        if not class_body:
            continue

        class_info = ClassInfo(
            name=class_name,
            header=filepath.name,
            base_class=base_class
        )
        
        class_info.is_detail_class = is_detail_class(class_name)

        # Extract fields and static methods from class body
        class_info.fields = extract_fields(class_body)
        class_info.static_methods = extract_static_methods(class_body)
        class_info.method_name_counts = extract_method_name_counts(class_body)

        # Value types are classes with fields and no public static methods
        class_info.is_value_type = len(class_info.fields) > 0 and len(class_info.static_methods) == 0
        
        # Only add if it has useful content
        if class_info.static_methods or class_info.fields or class_info.is_detail_class:
            classes.append(class_info)
    
    return classes

def scan_all_headers(root_dir: Path) -> Dict[str, ClassInfo]:
    """Scan all AA*.h files and build class database"""
    classes = {}
    
    for header_file in sorted(root_dir.glob('AA*.h')):
        if header_file.name in ['AADefines.h']:
            continue
        
        try:
            parsed_classes = parse_header_file(header_file)
            for cls in parsed_classes:
                classes[cls.name] = cls
        except Exception as e:
            print(f"Warning: Error parsing {header_file.name}: {e}")
    
    return classes


def _clang_is_public(cursor) -> bool:
    return cursor.access_specifier == clang.cindex.AccessSpecifier.PUBLIC


def _clang_is_field_type_supported(type_spelling: str) -> bool:
    type_spelling = type_spelling.replace('const', '').strip()
    if 'std::vector' in type_spelling or 'std::array' in type_spelling or 'std::filesystem' in type_spelling:
        return False
    if '<' in type_spelling or '>' in type_spelling:
        return False
    if type_spelling.startswith('CAA'):
        return True
    return type_spelling in {
        'double', 'float', 'long', 'int', 'bool', 'unsigned', 'unsigned long', 'unsigned int',
        'unsigned char', 'uint8_t', 'int32_t', 'uint32_t', 'size_t'
    }


def _clang_collect_class_info(header_file: Path, index: "clang.cindex.Index", args: List[str]) -> Dict[str, ClassInfo]:
    classes: Dict[str, ClassInfo] = {}

    try:
        tu = index.parse(
            str(header_file),
            args=args,
            options=clang.cindex.TranslationUnit.PARSE_SKIP_FUNCTION_BODIES,
        )
    except Exception:
        fallback_args = [a for a in args if a not in ("-Xclang", "-fretain-param-names")]
        tu = index.parse(
            str(header_file),
            args=fallback_args,
            options=clang.cindex.TranslationUnit.PARSE_SKIP_FUNCTION_BODIES,
        )

    for cursor in tu.cursor.walk_preorder():
        if not cursor.location.file:
            continue
        if Path(cursor.location.file.name) != header_file:
            continue
        if cursor.kind not in (clang.cindex.CursorKind.CLASS_DECL, clang.cindex.CursorKind.STRUCT_DECL):
            continue
        if not cursor.is_definition():
            continue
        if not cursor.spelling:
            continue

        class_name = cursor.spelling
        class_info = ClassInfo(
            name=class_name,
            header=header_file.name,
            base_class="",
        )
        class_info.is_detail_class = is_detail_class(class_name)

        method_name_counts: Dict[str, int] = {}

        for child in cursor.get_children():
            if child.kind == clang.cindex.CursorKind.CXX_BASE_SPECIFIER:
                class_info.base_class = child.type.spelling
            elif child.kind == clang.cindex.CursorKind.FIELD_DECL and _clang_is_public(child):
                token_text = " ".join([t.spelling for t in child.get_tokens()])
                if any(tok in token_text for tok in ("std::vector", "std::array", "std::filesystem", "std::basic_string", "std::string", "<", ">")):
                    continue
                field_type = child.type.spelling
                if _clang_is_field_type_supported(field_type):
                    class_info.fields.append((field_type, child.spelling))
            elif child.kind == clang.cindex.CursorKind.CXX_METHOD and child.is_static_method() and _clang_is_public(child):
                # Generated by Copilot
                # Tokens are space-separated, so check for "vector <" and "array <" patterns
                token_text = " ".join([t.spelling for t in child.get_tokens()])
                return_type = child.result_type.spelling
                if any(tok in token_text for tok in ("std :: vector", "vector <", "std :: array", "array <")):
                    return_type = "std::vector"

                params_parts = []
                for arg in child.get_arguments():
                    if arg.spelling:
                        params_parts.append(f"{arg.type.spelling} {arg.spelling}")
                    else:
                        params_parts.append(arg.type.spelling)
                params = ", ".join(params_parts)

                class_info.static_methods.append((return_type, child.spelling, params))
                method_name_counts[child.spelling] = method_name_counts.get(child.spelling, 0) + 1

        class_info.method_name_counts = method_name_counts
        class_info.is_value_type = len(class_info.fields) > 0 and len(class_info.static_methods) == 0

        if class_info.static_methods or class_info.fields or class_info.is_detail_class:
            classes[class_name] = class_info

    return classes


def scan_all_headers_with_clang(root_dir: Path) -> Dict[str, ClassInfo]:
    """Scan all AA*.h files using clang.cindex"""
    if not HAS_CLANG:
        raise RuntimeError("clang.cindex is not available. Install clang and libclang.")

    classes: Dict[str, ClassInfo] = {}
    index = clang.cindex.Index.create()
    args = [
        "-x", "c++",
        "-std=c++17",
        f"-I{root_dir}",
        "-DAAPLUS_EXT_CLASS=",
        "-Xclang", "-fretain-param-names",
    ]

    for header_file in sorted(root_dir.glob('AA*.h')):
        if header_file.name in ['AADefines.h']:
            continue
        try:
            parsed = _clang_collect_class_info(header_file, index, args)
            classes.update(parsed)
        except Exception as e:
            print(f"Warning: clang parse failed for {header_file.name}: {e}")

    return classes

def to_camel_case(name: str, convert: bool = False) -> str:
    """Convert method name to JavaScript camelCase"""
    # Generated by Copilot
    if not name or not convert:
        return name
    # Preserve single-character names as-is to avoid collisions (e.g., B vs b)
    if len(name) == 1:
        return name
    return name[0].lower() + name[1:]


def is_bindable_method(return_type: str, params: str) -> bool:
    """Heuristic filter for embind-compatible methods"""
    # Generated by Copilot
    # Skip raw pointer returns or params
    if '*' in return_type:
        return False
    if '*' in params:
        return False

    # Skip template containers (std::vector, std::array, etc.)
    if 'std::vector' in return_type or 'std::vector' in params:
        return False
    if 'std::array' in return_type or 'std::array' in params:
        return False

    # Skip function pointer typedefs
    if 'PROC' in return_type or 'PROC' in params:
        return False

    # Skip nested enum types - these require explicit binding
    # Includes both qualified (CAA*::EnumName) and unqualified enum names
    nested_enum_names = {'Algorithm', 'Correction', 'DOW', 'MoonAlgorithm', 'Object', 'Planet', 'REASON', 'Type'}
    if re.search(r'\bC?AA\w+::\w+', params) or re.search(r'\bC?AA\w+::\w+', return_type):
        return False
    # Check for unqualified enum names (clang may normalize them)
    for enum_name in nested_enum_names:
        if re.search(rf'\b{enum_name}\b', params):
            return False
        if re.search(rf'\b{enum_name}\b', return_type):
            return False

    # Skip non-const reference params (output params)
    if '&' in params:
        # Allow const references, skip non-const refs
        for part in params.split(','):
            part = part.strip()
            if '&' in part and 'const' not in part:
                return False

    # Skip function pointer params
    if '(*' in params:
        return False

    return True

def is_vsop87_variant(class_name: str) -> bool:
    """Check if class is a VSOP87 variant (A-E series)"""
    return bool(re.match(r'CAAVSOP87[A-E]_', class_name))

def generate_value_type_binding(cls: ClassInfo) -> List[str]:
    """Generate binding code for a value type"""
    lines = []
    lines.append(f'  value_object<{cls.name}>("{cls.name}")')
    
    for field_type, field_name in cls.fields:
        js_name = to_camel_case(field_name)
        lines.append(f'    .field("{js_name}", &{cls.name}::{field_name})')
    
    lines.append('    ;')
    return lines

def generate_class_binding(cls: ClassInfo, max_methods: int = 30, skipped_methods: Optional[List] = None) -> List[str]:
    """Generate binding code for a computational class"""
    # Generated by Copilot
    lines = []
    lines.append(f'  class_<{cls.name}>("{cls.name}")')
    
    # Add static methods
    method_count = 0
    for return_type, method_name, params in cls.static_methods:
        if method_count >= max_methods:
            lines.append(f'    // ... {len(cls.static_methods) - method_count} more methods available')
            break

        # Skip overloaded methods (require manual disambiguation)
        if cls.method_name_counts.get(method_name, 0) > 1:
            if skipped_methods is not None:
                skipped_methods.append({
                    'class': cls.name,
                    'method': method_name,
                    'return_type': return_type,
                    'params': params,
                    'reason': 'overloaded'
                })
            continue

        if not is_bindable_method(return_type, params):
            if skipped_methods is not None:
                reason = 'unknown'
                if '*' in return_type or '*' in params:
                    reason = 'pointer'
                elif 'std::vector' in return_type or 'std::vector' in params:
                    reason = 'std::vector'
                elif '&' in params and not any('const' in p for p in params.split(',')):
                    reason = 'non-const reference'
                else:
                    nested_enum_names = {'Algorithm', 'Correction', 'DOW', 'MoonAlgorithm', 'Object', 'Planet', 'REASON', 'Type'}
                    for enum_name in nested_enum_names:
                        if re.search(rf'\b{enum_name}\b', params):
                            reason = f'nested enum ({enum_name})'
                            break
                skipped_methods.append({
                    'class': cls.name,
                    'method': method_name,
                    'return_type': return_type,
                    'params': params,
                    'reason': reason
                })
            continue

        js_name = to_camel_case(method_name)
        lines.append(f'    .class_function("{js_name}", &{cls.name}::{method_name})')
        method_count += 1
    
    lines.append('    ;')
    return lines

def categorize_classes(classes: Dict[str, ClassInfo]) -> Dict[str, List[str]]:
    """Organize classes into logical categories"""
    categories = {
        'Version': ['CAAPlus'],
        'Value Types': [],
        'Date/Time': ['CAADate', 'CAACalendarDate', 'CAADynamicalTime'],
        'Sun': ['CAASun', 'CAAPhysicalSun'],
        'Moon': [],
        'Planets': ['CAAMercury', 'CAAVenus', 'CAAEarth', 'CAAMars', 'CAAJupiter', 
                    'CAASaturn', 'CAAUranus', 'CAANeptune', 'CAAPluto'],
        'Coordinate Transformations': ['CAACoordinateTransformation', 'CAAPrecession', 
                                       'CAANutation', 'CAAFK5', 'CAAAberration'],
        'Rise/Transit/Set': ['CAARiseTransitSet', 'CAARiseTransitSet2'],
        'Eclipses': ['CAAEclipses'],
        'Physical Ephemeris': ['CAAPhysicalMars', 'CAAPhysicalJupiter', 'CAAPhysicalMoon'],
        'Orbital Calculations': ['CAAElliptical', 'CAAParabolic', 'CAAHyperbolic', 
                                 'CAANearParabolic', 'CAAKepler', 'CAANodes'],
        'Planetary Phenomena': ['CAAPlanetaryPhenomena', 'CAAPlanetaryPhenomena2',
                                'CAAEquinoxesAndSolstices', 'CAAEquinoxesAndSolstices2',
                                'CAAPlanetPerihelionAphelion', 'CAAPlanetPerihelionAphelion2'],
        'Moons': ['CAAGalileanMoons', 'CAASaturnMoons', 'CAASaturnRings'],
        'Calendars': ['CAAEaster', 'CAAJewishCalendar', 'CAAMoslemCalendar'],
        'Miscellaneous': ['CAAAngularSeparation', 'CAADiameters', 'CAAGlobe', 
                          'CAAIlluminatedFraction', 'CAAInterpolate', 'CAAParallax',
                          'CAAParallactic', 'CAARefraction', 'CAASidereal', 
                          'CAAStellarMagnitudes', 'CAAEquationOfTime', 'CAABinaryStar',
                          'CAAEclipticalElements', 'CAAElementsPlanetaryOrbit'],
        'VSOP87 Core': ['CAAVSOP87', 'CAAVSOP2013', 'CAAELP2000', 'CAAELPMPP02'],
        'VSOP87 Variants': [],
    }
    
    # Populate value types
    for name, cls in classes.items():
        if cls.is_value_type:
            categories['Value Types'].append(name)
    
    # Populate Moon classes
    for name in classes:
        if 'Moon' in name and name not in categories['Moon'] and name not in categories['Physical Ephemeris']:
            categories['Moon'].append(name)
    
    # Populate VSOP87 variants
    for name in classes:
        if is_vsop87_variant(name):
            categories['VSOP87 Variants'].append(name)
    
    return categories

def generate_binding_code(classes: Dict[str, ClassInfo], include_vsop_variants: bool = True, skipped_methods: Optional[List] = None) -> str:
    """Generate the complete C++ embind code"""
    # Generated by Copilot
    if skipped_methods is None:
        skipped_methods = []
    
    code = []
    code.append('// Generated by Copilot - Comprehensive AA+ WASM Bindings')
    code.append('// Auto-generated from AA+ header files')
    code.append(f'// Total classes: {len(classes)}')
    code.append('')
    code.append('#include <emscripten/bind.h>')
    code.append('#include <string>')
    code.append('#include "AA+.h"')
    code.append('')
    code.append('using namespace emscripten;')
    code.append('')
    code.append('static std::string CAAPlus_Version() {')
    code.append('  return std::string(CAAPlus::Version());')
    code.append('}')
    code.append('')
    code.append('static double AA_DateToJD(long year, long month, long day, long hour, long minute, double second, bool gregorian) {')
    code.append('  CAADate date(year, month, static_cast<double>(day), static_cast<double>(hour), static_cast<double>(minute), second, gregorian);')
    code.append('  return date.Julian();')
    code.append('}')
    code.append('')
    code.append('EMSCRIPTEN_BINDINGS(aa_plus_comprehensive) {')
    
    # Categorize classes
    categories = categorize_classes(classes)
    
    # Track bound classes
    bound_classes = set()
    
    # Bind by category
    for category_name, class_list in categories.items():
        if not class_list:
            continue
        
        # Skip VSOP87 variants if not requested
        if category_name == 'VSOP87 Variants' and not include_vsop_variants:
            code.append(f'  // ============== {category_name} (Excluded for size optimization) ==============')
            code.append(f'  // {len(class_list)} variant classes available in full build')
            code.append('')
            continue
        
        code.append(f'  // ============== {category_name} ==============')
        
        for class_name in sorted(class_list):
            if class_name not in classes or class_name in bound_classes:
                continue
            
            cls = classes[class_name]
            
            # Special handling for version
            if class_name == 'CAAPlus':
                code.append('  function("version", &CAAPlus_Version);')
                code.append('  function("versionNumber", &CAAPlus::VersionNumber);')
                code.append('  function("dateToJD", &AA_DateToJD);')
                bound_classes.add(class_name)
                continue
            
            # Value types
            if cls.is_value_type or (category_name == 'Value Types' and cls.fields):
                code.extend(generate_value_type_binding(cls))
                bound_classes.add(class_name)
            # Computational classes
            elif cls.static_methods:
                code.extend(generate_class_binding(cls, skipped_methods=skipped_methods))
                bound_classes.add(class_name)
        
        code.append('')
    
    # Bind any remaining classes not in categories
    remaining = [name for name in sorted(classes.keys()) if name not in bound_classes]
    if remaining:
        code.append('  // ============== Other Classes ==============')
        for class_name in remaining:
            cls = classes[class_name]
            if cls.static_methods:
                code.extend(generate_class_binding(cls, max_methods=20, skipped_methods=skipped_methods))
        code.append('')
    
    code.append('}')
    code.append('')
    code.append('// Generated by Copilot')
    
    return '\n'.join(code)

def generate_class_list_markdown(classes: Dict[str, ClassInfo]) -> str:
    """Generate a markdown summary of all classes"""
    lines = []
    lines.append('# AA+ WASM Bindings - Class Summary')
    lines.append('')
    lines.append(f'Total classes found: **{len(classes)}**')
    lines.append('')
    
    categories = categorize_classes(classes)
    
    for category, class_list in categories.items():
        if not class_list:
            continue
        lines.append(f'## {category} ({len(class_list)} classes)')
        lines.append('')
        for class_name in sorted(class_list):
            if class_name in classes:
                cls = classes[class_name]
                methods = len(cls.static_methods)
                fields = len(cls.fields)
                info = []
                if fields > 0:
                    info.append(f'{fields} fields')
                if methods > 0:
                    info.append(f'{methods} methods')
                info_str = ', '.join(info) if info else 'empty'
                lines.append(f'- `{class_name}` - {info_str}')
        lines.append('')
    
    return '\n'.join(lines)


def generate_function_signatures(classes: Dict[str, ClassInfo]) -> Dict[str, Dict[str, List[Dict[str, str]]]]:
    """Generate a JSON-serializable map of class -> method -> param metadata"""
    signatures: Dict[str, Dict[str, List[Dict[str, str]]]] = {}

    for cls in classes.values():
        if not cls.static_methods:
            continue
        method_map: Dict[str, List[Dict[str, str]]] = {}
        for return_type, method_name, params in cls.static_methods:
            params_list = []
            if params:
                for p in params.split(','):
                    p = p.strip()
                    if not p:
                        continue
                    # Basic split: type + name (name may be missing)
                    parts = p.rsplit(' ', 1)
                    if len(parts) == 2:
                        ptype, pname = parts
                    else:
                        ptype, pname = parts[0], ""
                    params_list.append({"type": ptype.strip(), "name": pname.strip()})
            method_map[method_name] = params_list
        if method_map:
            signatures[cls.name] = method_map

    return signatures


def _cpp_type_to_ts(cpp_type: str) -> str:
    """Convert C++ type to TypeScript type"""
    # Generated by Copilot
    cpp_type = cpp_type.strip()
    # Remove const and references
    cpp_type = cpp_type.replace('const ', '').replace('&', '').strip()
    
    # Primitive mappings
    if cpp_type in ('double', 'float', 'int', 'long', 'unsigned', 'unsigned int', 
                    'unsigned long', 'size_t', 'int32_t', 'uint32_t', 'long long'):
        return 'number'
    if cpp_type == 'bool':
        return 'boolean'
    if cpp_type in ('std::string', 'string'):
        return 'string'
    if cpp_type == 'void':
        return 'void'
    # CAA* types are returned as their class name
    if cpp_type.startswith('CAA'):
        return cpp_type
    # Default to any for unknown types
    return 'any'


def generate_typescript_definitions(classes: Dict[str, ClassInfo]) -> str:
    """Generate TypeScript definition file with proper parameter names"""
    # Generated by Copilot
    lines = [
        '// TypeScript definitions for AA+ WASM bindings',
        '// Generated by Copilot',
        '',
        'export interface ClassHandle {',
        '  isAliasOf(other: ClassHandle): boolean;',
        '  delete(): void;',
        '  deleteLater(): this;',
        '  isDeleted(): boolean;',
        '  clone(): this;',
        '}',
        '',
    ]
    
    # Separate value types and class types
    value_types = [c for c in classes.values() if c.is_value_type or c.is_detail_class]
    class_types = [c for c in classes.values() if not c.is_value_type and not c.is_detail_class]
    
    # Generate value type interfaces
    for cls in sorted(value_types, key=lambda c: c.name):
        lines.append(f'export type {cls.name} = {{')
        for field_type, field_name in cls.fields:
            js_name = to_camel_case(field_name)
            ts_type = _cpp_type_to_ts(field_type)
            lines.append(f'  {js_name}: {ts_type};')
        lines.append('};')
        lines.append('')
    
    # Generate class interfaces
    for cls in sorted(class_types, key=lambda c: c.name):
        lines.append(f'export interface {cls.name} extends ClassHandle {{')
        lines.append('}')
        lines.append('')
    
    # Generate module interface with static methods
    lines.append('export interface MainModule {')
    lines.append('  // Helper functions')
    lines.append('  dateToJD(year: number, month: number, day: number, hour?: number, minute?: number, second?: number): number;')
    lines.append('')
    
    for cls in sorted(classes.values(), key=lambda c: c.name):
        if not cls.static_methods:
            continue
        
        # Filter to bindable methods only
        bindable_methods = []
        for return_type, method_name, params in cls.static_methods:
            if cls.method_name_counts.get(method_name, 0) > 1:
                continue
            if not is_bindable_method(return_type, params):
                continue
            bindable_methods.append((return_type, method_name, params))
        
        if not bindable_methods:
            continue
            
        lines.append(f'  {cls.name}: {{')
        for return_type, method_name, params in bindable_methods:
            js_name = to_camel_case(method_name)
            ts_return = _cpp_type_to_ts(return_type)
            
            # Parse parameters
            ts_params = []
            if params:
                for p in params.split(','):
                    p = p.strip()
                    if not p:
                        continue
                    parts = p.rsplit(' ', 1)
                    if len(parts) == 2:
                        ptype, pname = parts
                    else:
                        ptype, pname = parts[0], f'arg{len(ts_params)}'
                    # Handle default values
                    if '=' in pname:
                        pname = pname.split('=')[0].strip()
                        pname = f'{pname}?'
                    ts_type = _cpp_type_to_ts(ptype)
                    ts_params.append(f'{pname}: {ts_type}')
            
            params_str = ', '.join(ts_params)
            lines.append(f'    {js_name}({params_str}): {ts_return};')
        lines.append('  };')
    
    lines.append('}')
    lines.append('')
    lines.append('declare const Module: MainModule;')
    lines.append('export default Module;')
    lines.append('')
    
    return '\n'.join(lines)


def main():
    import sys
    
    script_dir = Path(__file__).parent
    root_dir = script_dir.parent  # Go up to aaplus root
    
    # Parse command line arguments
    include_vsop_variants = '--no-vsop-variants' not in sys.argv
    use_clang = '--use-clang' in sys.argv
    
    print("Scanning AA+ headers...")
    if use_clang:
        if not HAS_CLANG:
            raise RuntimeError("--use-clang requested but clang.cindex is not available")
        classes = scan_all_headers_with_clang(root_dir)
    else:
        classes = scan_all_headers(root_dir)
    print(f"✓ Found {len(classes)} classes")
    
    # Generate comprehensive bindings
    print("\nGenerating comprehensive binding code...")
    skipped_methods = []
    binding_code = generate_binding_code(classes, include_vsop_variants=include_vsop_variants, skipped_methods=skipped_methods)
    
    output_file = script_dir / 'bindings' / 'aa_bindings.cpp'
    output_file.parent.mkdir(parents=True, exist_ok=True)
    
    with open(output_file, 'w') as f:
        f.write(binding_code)
    
    print(f"✓ Generated: {output_file}")
    
    # Generate class summary
    summary = generate_class_list_markdown(classes)
    summary_file = script_dir / 'CLASS_SUMMARY.md'
    with open(summary_file, 'w') as f:
        f.write(summary)
    print(f"✓ Generated: {summary_file}")

    # Generate function signatures JSON
    signatures = generate_function_signatures(classes)
    signatures_file = script_dir / 'function_signatures.json'
    with open(signatures_file, 'w') as f:
        json.dump(signatures, f, indent=2)
    print(f"✓ Generated: {signatures_file}")

    # Generate TypeScript definitions with proper parameter names
    ts_code = generate_typescript_definitions(classes)
    ts_file = script_dir / 'dist' / 'aaplus.d.ts'
    ts_file.parent.mkdir(parents=True, exist_ok=True)
    with open(ts_file, 'w') as f:
        f.write(ts_code)
    print(f"✓ Generated: {ts_file}")

    # Generate skipped methods report
    if skipped_methods:
        skipped_file = script_dir / 'SKIPPED_METHODS.json'
        with open(skipped_file, 'w') as f:
            json.dump(skipped_methods, f, indent=2)
        print(f"✓ Generated: {skipped_file}")
        
        # Generate summary by reason
        reasons_count = {}
        for item in skipped_methods:
            reason = item['reason']
            reasons_count[reason] = reasons_count.get(reason, 0) + 1
        
        print(f"\n  Skipped {len(skipped_methods)} methods:")
        for reason, count in sorted(reasons_count.items(), key=lambda x: -x[1]):
            print(f"    - {reason}: {count}")
    
    # Print summary
    print(f"\nSummary:")
    value_types = len([c for c in classes.values() if c.is_value_type or c.is_detail_class])
    vsop_variants = len([c for c in classes.values() if is_vsop87_variant(c.name)])
    core_classes = len(classes) - value_types - vsop_variants
    
    print(f"  - Value types/structs: {value_types}")
    print(f"  - Core computational classes: {core_classes}")
    print(f"  - VSOP87 variants: {vsop_variants}")
    print(f"  - Total: {len(classes)}")
    
    if not include_vsop_variants:
        print(f"\n  Note: VSOP87 variants excluded (use full build to include)")

if __name__ == '__main__':
    main()

